    #[test]
    fn test_main_store_protected_from_return_fold_issue_9157() {
        // Same shape as `test_const_arg_slot_return_folds_to_immediate_issue_8443`,
        // but compiled as MAIN/global code with slot 3 marked as a genuinely
        // surviving main-scope binding: the store must survive so
        // `Vm::get_global` can read the slot back for REPL session persistence
        // across evaluations (Issue #9157).
        let code = vec![
            Instr::PushI64(41),
            Instr::StoreSlotI64(3),
            Instr::LoadAddConstI64Slot(3, 1),
            Instr::ReturnI64,
        ];
        let protected_slots = HashSet::from([3]);

        let (optimized, _mapping) = optimize_protecting_main_stores(
            code,
            MainStoreProtection {
                main_entry: 0,
                protected_slots: &protected_slots,
            },
        );

        assert_eq!(optimized.len(), 4);
        assert!(matches!(optimized[0], Instr::PushI64(41)));
        assert!(matches!(optimized[1], Instr::StoreSlotI64(3)));
        assert!(matches!(optimized[2], Instr::LoadAddConstI64Slot(3, 1)));
        assert!(matches!(optimized[3], Instr::ReturnI64));
    }

    #[test]
    fn test_main_store_protected_from_raw_add_return_fold_issue_9157() {
        // Same raw (unfused) shape as
        // `test_const_arg_slot_raw_add_return_folds_to_immediate_issue_8443`,
        // compiled as MAIN/global code with slot 3 protected. With Pattern 0
        // skipped for slot 3, `LoadSlotI64(3); PushI64(1); AddI64` still
        // legitimately fuses into `LoadAddConstI64Slot(3, 1)` via the unrelated
        // (and safe) Pattern 2b superinstruction — that fusion only touches the
        // load/arithmetic computing the return value, not the store. What must
        // NOT happen is the `StoreSlotI64(3)` disappearing, since that is the
        // write `Vm::get_global` reads back for REPL session persistence
        // (Issue #9157).
        let code = vec![
            Instr::PushI64(41),
            Instr::StoreSlotI64(3),
            Instr::LoadSlotI64(3),
            Instr::PushI64(1),
            Instr::AddI64,
            Instr::ReturnI64,
        ];
        let protected_slots = HashSet::from([3]);

        let (optimized, _mapping) = optimize_protecting_main_stores(
            code,
            MainStoreProtection {
                main_entry: 0,
                protected_slots: &protected_slots,
            },
        );

        assert!(
            optimized
                .iter()
                .any(|instr| matches!(instr, Instr::StoreSlotI64(3))),
            "main-frame store for slot 3 must survive; got {optimized:?}"
        );
        assert!(matches!(optimized.last(), Some(Instr::ReturnI64)));
    }

    #[test]
    fn test_unprotected_main_slot_still_folds_issue_9157() {
        // Same shape and `main_entry`, but slot 3 is NOT in `protected_slots` —
        // e.g. a `let`-local that shares the main frame's slot numbering but
        // was restored out of `initialized_locals` by the time compilation
        // finished (Issue #9157). Its store must still get the standard
        // elimination: a `let` block introducing a brand-new name must not
        // leak that name into `Vm::get_global`-based REPL persistence just
        // because main-frame stores are now selectively protected.
        let code = vec![
            Instr::PushI64(41),
            Instr::StoreSlotI64(3),
            Instr::LoadAddConstI64Slot(3, 1),
            Instr::ReturnI64,
        ];
        let protected_slots = HashSet::new();

        let (optimized, _mapping) = optimize_protecting_main_stores(
            code,
            MainStoreProtection {
                main_entry: 0,
                protected_slots: &protected_slots,
            },
        );

        assert_eq!(optimized.len(), 2);
        assert!(matches!(optimized[0], Instr::PushI64(42)));
        assert!(matches!(optimized[1], Instr::ReturnI64));
    }

    #[test]
    fn test_function_body_before_main_entry_still_folds_issue_9157() {
        // A function body compiled entirely BEFORE `main_entry` still gets the
        // standard elimination: its frame is discarded on return, so the store
        // genuinely has no observable use, even if its slot number happens to
        // match a protected main-frame slot (different physical frame). Only
        // code at/after `main_entry` is eligible for protection.
        let code = vec![
            Instr::PushI64(41),
            Instr::StoreSlotI64(3),
            Instr::LoadAddConstI64Slot(3, 1),
            Instr::ReturnI64,
        ];
        let protected_slots = HashSet::from([3]);

        let (optimized, _mapping) = optimize_protecting_main_stores(
            code,
            MainStoreProtection {
                main_entry: 4,
                protected_slots: &protected_slots,
            },
        );

        assert_eq!(optimized.len(), 2);
        assert!(matches!(optimized[0], Instr::PushI64(42)));
        assert!(matches!(optimized[1], Instr::ReturnI64));
    }

