    #[test]
    fn test_accum_f64_slots_fusion_issue_9126() {
        // Pure-F64 accumulate `s = s + x` (dst == lhs).
        let accum = vec![
            Instr::LoadSlotF64(1),
            Instr::LoadSlotF64(2),
            Instr::AddF64,
            Instr::StoreSlotF64(1),
        ];
        let (optimized, mapping) = optimize(accum);
        assert_eq!(optimized.len(), 1);
        assert!(matches!(optimized[0], Instr::AddF64Slots(1, 1, 2)));
        assert_eq!(mapping, vec![0, 0, 0, 0, 1]);

        // General 3-slot add `c = a + b` (dst != lhs != rhs).
        let three_slot = vec![
            Instr::LoadSlotF64(3),
            Instr::LoadSlotF64(4),
            Instr::AddF64,
            Instr::StoreSlotF64(5),
        ];
        let (optimized, _) = optimize(three_slot);
        assert_eq!(optimized.len(), 1);
        assert!(matches!(optimized[0], Instr::AddF64Slots(5, 3, 4)));

        // Already-fused I64→F64 rhs: `s = s + F64(i)` with LoadSlotI64ToF64.
        let prefused = vec![
            Instr::LoadSlotF64(1),
            Instr::LoadSlotI64ToF64(3),
            Instr::AddF64,
            Instr::StoreSlotF64(1),
        ];
        let (optimized, _) = optimize(prefused);
        assert_eq!(optimized.len(), 1);
        assert!(matches!(optimized[0], Instr::AddF64I64Slots(1, 1, 3)));

        // Un-fused I64→F64 rhs (5-instruction window): the LoadSlotI64 +
        // CallBuiltin(Float64) conversion is still separate during the single
        // optimize pass, so the whole `s += F64(i)` body must fold at once.
        let i64_conv = vec![
            Instr::LoadSlotF64(1),
            Instr::LoadSlotI64(3),
            Instr::CallBuiltin(BuiltinId::Float64, 1),
            Instr::AddF64,
            Instr::StoreSlotF64(1),
        ];
        let (optimized, mapping) = optimize(i64_conv);
        assert_eq!(optimized.len(), 1);
        assert!(matches!(optimized[0], Instr::AddF64I64Slots(1, 1, 3)));
        assert_eq!(mapping, vec![0, 0, 0, 0, 0, 1]);
    }

    #[test]
    fn test_accum_f64_slots_respects_jump_target_boundary_issue_9126() {
        // A jump into the middle of the window must prevent fusion so the jump
        // still lands on a real instruction.
        let code = vec![
            Instr::LoadSlotF64(1),
            Instr::LoadSlotF64(2),
            Instr::AddF64,
            Instr::StoreSlotF64(1),
            Instr::JumpIfZero(2), // targets index 2 (the AddF64 mid-window)
        ];
        let (optimized, _) = optimize(code);
        // Not fused into AddF64Slots: the mid-window jump target blocks it.
        assert!(!matches!(optimized[0], Instr::AddF64Slots(..)));
    }

