    #[test]
    fn test_f64_compare_jump_false_branch_fusion() {
        let code = vec![
            Instr::LeF64,
            Instr::JumpIfZero(4),
            Instr::PushI64(1),
            Instr::Jump(5),
            Instr::PushI64(2),
        ];

        let (optimized, mapping) = optimize(code);

        assert_eq!(optimized.len(), 4);
        assert_eq!(mapping, vec![0, 0, 1, 2, 3, 4]);
        assert!(matches!(optimized[0], Instr::JumpIfNotLeF64(3)));
        assert!(matches!(optimized[2], Instr::Jump(4)));

        let fusions = vec![
            (vec![Instr::NeF64, Instr::JumpIfZero(10)], "eq"),
            (vec![Instr::EqF64, Instr::JumpIfZero(10)], "ne"),
            (vec![Instr::LtF64, Instr::JumpIfZero(10)], "not_lt"),
            (vec![Instr::GtF64, Instr::JumpIfZero(10)], "not_gt"),
            (vec![Instr::LeF64, Instr::JumpIfZero(10)], "not_le"),
            (vec![Instr::GeF64, Instr::JumpIfZero(10)], "not_ge"),
        ];

        for (code, expected) in fusions {
            let (optimized, _) = optimize(code);
            assert_eq!(optimized.len(), 1);
            match (expected, &optimized[0]) {
                ("eq", Instr::JumpIfEqF64(10))
                | ("ne", Instr::JumpIfNeF64(10))
                | ("not_lt", Instr::JumpIfNotLtF64(10))
                | ("not_gt", Instr::JumpIfNotGtF64(10))
                | ("not_le", Instr::JumpIfNotLeF64(10))
                | ("not_ge", Instr::JumpIfNotGeF64(10)) => {}
                _ => panic!("unexpected F64 compare jump fusion: {:?}", optimized[0]),
            }
        }
    }

